A = {0,1,2,3,5,6}
B = {4,7,8,9,10}
# Check fixed edges are between parts
for u,v in [(1,10),(0,4),(0,8),(2,9)]:
    assert (u in A) != (v in A), (u,v)
    assert (u in A) ^ (v in A)

# Use complete bipartite K_{6,5}
edges = []
for a in A:
    for b in B:
        u,v = min(a,b), max(a,b)
        edges.append((u,v))
edges.sort()
print(len(edges), edges)

# Verify degrees
from collections import Counter
deg = Counter()
for u,v in edges:
    deg[u]+=1; deg[v]+=1
print(deg)
print("min deg:", min(deg.values()))
